{
  "summary": "MA3+PER now leads, improving AIC by 3.084 over MA3 and 3.575 over MA3*PER. Constant means beat richer means in tested comparisons, but MA3+PER's mean remains untested. Final tests vary stationary smoothness, multiscale behavior, and mean around this leader, then explore amplitude modulation of either additive component. Poor SE+LIN performance does not exclude these nonstationary alternatives.",
  "proposals": [
    {"kernel_id": 32, "mean_id": 2, "reason": "Replace MA3 with smoother MA5, retaining additive periodicity and constant mean."},
    {"kernel_id": 36, "mean_id": 2, "reason": "Replace MA3 with multiscale RQ while preserving periodic component and mean."},
    {"kernel_id": 27, "mean_id": 3, "reason": "Isolate linear versus constant mean within the leading covariance."},
    {"kernel_id": 64, "mean_id": 2, "reason": "Explore linear amplitude modulation of MA3 while retaining independent periodic covariance."},
    {"kernel_id": 92, "mean_id": 2, "reason": "Explore linear amplitude modulation of periodic covariance while retaining independent MA3."},
    {"kernel_id": 4, "mean_id": 2, "reason": "Provide standalone MA5 control for the smoother additive periodic candidate."},
    {"kernel_id": 46, "mean_id": 2, "reason": "Explore locally periodic SE modulation alongside independent MA3."}
  ]
}
